//! Shell completion scripts, generated by clap_complete from Clap's live command
//! tree, so they keep up with every subcommand and flag.
use anyhow::Result;
use clap::{Command, ValueEnum};

/// The shells `rustunes completions` writes a script for.
#[derive(Clone, Copy, Debug, PartialEq, Eq, ValueEnum)]
pub enum Shell {
    Bash,
    Zsh,
    Fish,
}

impl Shell {
    pub fn name(self) -> &'static str {
        match self {
            Shell::Bash => "bash",
            Shell::Zsh => "zsh",
            Shell::Fish => "fish",
        }
    }
}

/// The completion script for `shell`. It is built in memory: clap_complete
/// panics when a write fails, and stdout may be a pipe that has closed.
pub fn script(shell: Shell, mut command: Command) -> Result<String> {
    let generator = match shell {
        Shell::Bash => clap_complete::Shell::Bash,
        Shell::Zsh => clap_complete::Shell::Zsh,
        Shell::Fish => clap_complete::Shell::Fish,
    };
    let mut script = Vec::new();
    clap_complete::generate(generator, &mut command, "rustunes", &mut script);
    Ok(String::from_utf8(script)?)
}
